<?php
declare(strict_types=1);
namespace App\Jobs\QaReply;
use App\Enums\UserStatus; use App\Models\QaReply; use App\Models\User; use App\Notifications\QaReplyReceivedNotification; use App\Services\Notifications\NotificationAttemptTracker; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Queue\Middleware\WithoutOverlapping; use Illuminate\Queue\SerializesModels; use Illuminate\Support\Facades\Notification; use Throwable;
final class QaReplyMailNotificationJob implements ShouldQueue {use Dispatchable,Queueable,SerializesModels,InteractsWithQueue;public int $tries=0;public function __construct(public readonly string $replyId,public readonly string $recipientId){}public function backoff():array{return[60,300];}public function middleware():array{return[(new WithoutOverlapping('qa-reply-mail:'.$this->replyId.':'.$this->recipientId))->releaseAfter(10)->expireAfter(300)];}public function handle():void{$r=QaReply::find($this->replyId);$u=User::find($this->recipientId);if(!$r||!$u||$u->id===$r->user_id||$u->status!==UserStatus::InProgress)return;$count=app(NotificationAttemptTracker::class)->increment('qa_reply:'.$this->replyId,$this->recipientId,'mail');if($count>3){$this->fail(new \RuntimeException('notification delivery attempts exceeded'));return;}try{Notification::sendNow($u,new QaReplyReceivedNotification($r),['mail']);}catch(Throwable $e){if($count>=3){$this->fail($e);return;}throw $e;}}}
